<?php
require_once __DIR__ . '/includes/functions.php';$u=require_role('business_owner');$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['consent_id']??0);$s=$pdo->prepare('UPDATE consents SET revoked_at=NOW() WHERE id=? AND business_user_id=? AND revoked_at IS NULL');$s->execute([$id,$u['id']]);if($s->rowCount()){$s=$pdo->prepare("INSERT INTO consent_events (business_user_id,lender_user_id,criteria_id,event_type,details) SELECT business_user_id,lender_user_id,criteria_id,'revoked','Owner revoked lender access' FROM consents WHERE id=?");$s->execute([$id]);flash('success',t('Access revoked. The lender can no longer view this profile through CreditReady.','Accès révoqué. Le prêteur ne peut plus consulter ce profil via CreditReady.'));}redirect('consents.php');}
$s=$pdo->prepare('SELECT c.*,lc.institution_name,u.business_name AS lender_business,u.full_name AS lender_name FROM consents c JOIN users u ON u.id=c.lender_user_id LEFT JOIN lender_criteria lc ON lc.id=c.criteria_id WHERE c.business_user_id=? ORDER BY c.consented_at DESC');$s->execute([$u['id']]);$rows=$s->fetchAll();$pageTitle=t('Consent management','Gestion du consentement');require __DIR__.'/includes/header.php';
?>
<div class="dashboard-heading"><div><span class="eyebrow"><?= e(t('YOUR INFORMATION, YOUR CHOICE','VOS INFORMATIONS, VOTRE CHOIX')) ?></span><h1><?= e(t('Manage data sharing','Gérer le partage des données')) ?></h1><p><?= e(t('See who you have authorised and revoke future access whenever you choose.','Consultez les autorisations accordées et révoquez l’accès futur quand vous le souhaitez.')) ?></p></div></div><div class="notice-box"><span class="notice-icon">✓</span><p><?= e(t('Consent is specific to a lender and a review purpose. Revoking access stops future CreditReady access; it cannot retrieve copies already lawfully downloaded by a lender.','Le consentement concerne un prêteur et un objectif précis. La révocation bloque l’accès futur via CreditReady, mais ne peut pas récupérer les copies déjà téléchargées légalement par un prêteur.')) ?></p></div>
<section class="panel"><?php if(!$rows): ?><p class="empty-state"><?= e(t('You have not shared your profile with any lender.','Vous n’avez partagé votre profil avec aucun prêteur.')) ?></p><?php else: ?><div class="table-wrap"><table><thead><tr><th><?= e(t('Lender','Prêteur')) ?></th><th><?= e(t('Purpose','Objectif')) ?></th><th><?= e(t('Granted','Accordé le')) ?></th><th><?= e(t('Status','Statut')) ?></th><th><?= e(t('Action','Action')) ?></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?= e($r['institution_name']?:$r['lender_business']?:$r['lender_name']) ?></strong></td><td><?= e($r['consent_purpose']) ?></td><td><?= e($r['consented_at']) ?></td><td><span class="pill <?= $r['revoked_at']?'pill-amber':'pill-green' ?>"><?= e($r['revoked_at']?t('Revoked','Révoqué'):t('Active','Actif')) ?></span></td><td><?php if(!$r['revoked_at']): ?><form method="post" onsubmit="return confirm('<?= e(t('Revoke this lender’s access?','Révoquer l’accès de ce prêteur ?')) ?>')"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="consent_id" value="<?= (int)$r['id'] ?>"><button class="btn btn-danger btn-small" type="submit"><?= e(t('Revoke access','Révoquer')) ?></button></form><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
